// Normalizar y validar entrada
const body = $input.first().json;

// Validar entrada requerida
if (!body.query) {
  throw new Error('Query es requerida');
}

if (!body.context) {
  throw new Error('Contexto es requerido');
}

const { query, context } = body;
const { studentId, courseId, conversationId } = context;

// Validar contexto requerido
if (!studentId || !courseId) {
  throw new Error('studentId y courseId son requeridos');
}

// Preparar datos normalizados
const normalizedData = {
  query: query.trim(),
  studentId,
  courseId,
  conversationId: conversationId || `conv-${Date.now()}`,
  timestamp: new Date().toISOString(),
  metadata: {
    source: 'audio-tutor-multi-agent',
    version: '2.0.0'
  }
};

return {
  json: normalizedData
};

// Combinar contextos de personalización
const normalizedData = $('Normalize Inputs').first().json;
const pedagogicalSettings = $('Load Pedagogical Context').first().json[0] || {};
const studentProfile = $('Load Student Profile').first().json[0] || {};
const conversationContext = $('Load Conversation Context').first().json[0] || {};

// Crear contexto personalizado
const personalizedContext = {
  ...normalizedData,
  pedagogicalSettings: {
    teachingStyle: pedagogicalSettings.teaching_style || 'directo',
    tonePreference: pedagogicalSettings.tone_preference || 'amigable',
    detailLevel: pedagogicalSettings.detail_level || 'medio',
    useExamples: pedagogicalSettings.use_examples || true,
    encourageQuestions: pedagogicalSettings.encourage_questions || true,
    voiceName: pedagogicalSettings.voice_name || 'Kore',
    voiceSpeed: pedagogicalSettings.voice_speed || 1.0,
    systemPromptOverride: pedagogicalSettings.system_prompt_override
  },
  studentProfile: {
    learningStyle: studentProfile.preferred_learning_style || 'visual',
    topicsStruggled: studentProfile.topics_struggled || [],
    topicsMastered: studentProfile.topics_mastered || [],
    difficultyLevel: studentProfile.difficulty_level || 'medio',
    preferredExamples: studentProfile.preferred_examples || 'practicos'
  },
  conversationContext: {
    conversationId: conversationContext.id,
    startedAt: conversationContext.started_at,
    lastActivity: conversationContext.last_activity_at,
    metadata: conversationContext.metadata || {}
  }
};

// Generar system prompt personalizado
const systemPrompt = generatePersonalizedPrompt(personalizedContext);

return {
  json: {
    ...personalizedContext,
    systemPrompt
  }
};

function generatePersonalizedPrompt(context) {
  const { pedagogicalSettings, studentProfile, conversationContext } = context;

  let prompt = `Eres EduSpark, un tutor de IA especializado en educación personalizada.\n\n`;

  // Estilo pedagógico del docente
  prompt += `ESTILO PEDAGÓGICO DEL DOCENTE:\n`;
  prompt += `- Metodología: ${pedagogicalSettings.teachingStyle}\n`;
  prompt += `- Tono: ${pedagogicalSettings.tonePreference}\n`;
  prompt += `- Nivel de detalle: ${pedagogicalSettings.detailLevel}\n`;

  if (pedagogicalSettings.useExamples) {
    prompt += `- Incluye ejemplos prácticos\n`;
  }

  if (pedagogicalSettings.encourageQuestions) {
    prompt += `- Fomenta preguntas del estudiante\n`;
  }

  if (pedagogicalSettings.systemPromptOverride) {
    prompt += `- Instrucciones especiales: ${pedagogicalSettings.systemPromptOverride}\n`;
  }

  prompt += `\n`;

  // Perfil del estudiante
  prompt += `PERFIL DEL ESTUDIANTE:\n`;
  prompt += `- Estilo de aprendizaje: ${studentProfile.learningStyle}\n`;

  if (studentProfile.topicsStruggled && studentProfile.topicsStruggled.length > 0) {
    prompt += `- Temas que requieren refuerzo: ${studentProfile.topicsStruggled.join(', ')}\n`;
  }

  if (studentProfile.topicsMastered && studentProfile.topicsMastered.length > 0) {
    prompt += `- Temas dominados: ${studentProfile.topicsMastered.join(', ')}\n`;
  }

  prompt += `- Nivel de dificultad: ${studentProfile.difficultyLevel}\n`;
  prompt += `- Ejemplos preferidos: ${studentProfile.preferredExamples}\n`;

  prompt += `\n`;

  // Instrucciones de personalización
  prompt += `INSTRUCCIONES DE PERSONALIZACIÓN:\n`;
  prompt += `1. Adapta tu respuesta al estilo pedagógico del docente\n`;
  prompt += `2. Considera el estilo de aprendizaje del estudiante\n`;
  prompt += `3. Usa ejemplos apropiados para el nivel del estudiante\n`;
  prompt += `4. Mantén un tono ${pedagogicalSettings.tonePreference}\n`;
  prompt += `5. Proporciona nivel de detalle ${pedagogicalSettings.detailLevel}\n`;

  if (pedagogicalSettings.teachingStyle === 'socratico') {
    prompt += `6. Usa preguntas guiadas para fomentar el descubrimiento\n`;
  } else if (pedagogicalSettings.teachingStyle === 'directo') {
    prompt += `6. Proporciona explicaciones claras y estructuradas\n`;
  } else if (pedagogicalSettings.teachingStyle === 'constructivista') {
    prompt += `6. Ayuda al estudiante a construir su propio conocimiento\n`;
  }

  if (studentProfile.learningStyle === 'visual') {
    prompt += `7. Incluye referencias visuales, diagramas y ejemplos gráficos\n`;
  } else if (studentProfile.learningStyle === 'auditory') {
    prompt += `7. Usa analogías sonoras y explicaciones verbales\n`;
  } else if (studentProfile.learningStyle === 'kinesthetic') {
    prompt += `7. Incluye actividades prácticas y experimentos\n`;
  }

  prompt += `\n`;
  prompt += `IMPORTANTE: Responde basándote ÚNICAMENTE en el contexto del material del curso. Si no encuentras la información, di claramente que no está disponible en el material.`;

  return prompt;
}

// Preparar consulta para búsqueda vectorial
const personalizedContext = $('Merge Personalization Context').first().json;
const courseMaterials = $('Load Course Materials').first().json;

// Crear consulta enriquecida con contexto personalizado
const enrichedQuery = `${personalizedContext.query}\n\nContexto del estudiante: ${personalizedContext.studentProfile.learningStyle}\nEstilo pedagógico: ${personalizedContext.pedagogicalSettings.teachingStyle}\nNivel de detalle: ${personalizedContext.pedagogicalSettings.detailLevel}`;

// Preparar materiales para búsqueda
const materials = courseMaterials.map(material => ({
  id: material.id,
  title: material.title,
  content: material.content,
  type: material.type,
  metadata: material.metadata || {}
}));

return {
  json: {
    ...personalizedContext,
    enrichedQuery,
    materials,
    searchContext: {
      courseId: personalizedContext.courseId,
      studentId: personalizedContext.studentId,
      learningStyle: personalizedContext.studentProfile.learningStyle,
      teachingStyle: personalizedContext.pedagogicalSettings.teachingStyle
    }
  }
};

// Búsqueda vectorial simple (simulada)
const personalizedContext = $('Prepare Vector Search').first().json;
const queryEmbedding = $('Generate Query Embedding').first().json.data[0].embedding;

// Simular búsqueda vectorial
const materials = personalizedContext.materials;
const query = personalizedContext.enrichedQuery.toLowerCase();

// Buscar materiales relevantes
const relevantMaterials = materials
  .map(material => {
    const content = material.content.toLowerCase();
    const title = material.title.toLowerCase();

    // Calcular relevancia simple basada en palabras clave
    const queryWords = query.split(' ');
    let relevance = 0;

    queryWords.forEach(word => {
      if (content.includes(word)) relevance += 0.1;
      if (title.includes(word)) relevance += 0.2;
    });

    return {
      ...material,
      relevance: Math.min(relevance, 1.0)
    };
  })
  .filter(material => material.relevance > 0.1)
  .sort((a, b) => b.relevance - a.relevance)
  .slice(0, 5); // Top 5 materiales más relevantes

// Crear contexto RAG
const ragContext = relevantMaterials
  .map(material => `**${material.title}**\n${material.content.substring(0, 500)}...`)
  .join('\n\n');

return {
  json: {
    ...personalizedContext,
    ragContext,
    relevantMaterials,
    queryEmbedding
  }
};

// Formatear respuesta con personalización
const personalizedContext = $('Vector Search').first().json;
const geminiResponse = $('Generate Answer').first().json;

// Extraer respuesta del texto generado
const responseText = geminiResponse.text || geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || 'No se pudo generar respuesta';

// Crear fuentes basadas en materiales relevantes
const sources = personalizedContext.relevantMaterials
  .filter(material => material.relevance > 0.3)
  .map(material => ({
    title: material.title,
    url: material.metadata?.url || `#${material.id}`,
    relevance: material.relevance,
    type: material.type
  }));

// Crear metadatos de personalización
const personalization = {
  appliedStyle: personalizedContext.pedagogicalSettings.teachingStyle,
  learningStyle: personalizedContext.studentProfile.learningStyle,
  examplesIncluded: personalizedContext.pedagogicalSettings.useExamples,
  questionsEncouraged: personalizedContext.pedagogicalSettings.encourageQuestions,
  detailLevel: personalizedContext.pedagogicalSettings.detailLevel,
  toneApplied: personalizedContext.pedagogicalSettings.tonePreference,
  voiceSettings: {
    name: personalizedContext.pedagogicalSettings.voiceName,
    speed: personalizedContext.pedagogicalSettings.voiceSpeed
  }
};

// Crear respuesta final
const response = {
  response: responseText,
  sources,
  personalization,
  metadata: {
    timestamp: new Date().toISOString(),
    conversationId: personalizedContext.conversationId,
    courseId: personalizedContext.courseId,
    studentId: personalizedContext.studentId,
    query: personalizedContext.query,
    materialsUsed: personalizedContext.relevantMaterials.length,
    processingTime: Date.now() - new Date(personalizedContext.timestamp).getTime()
  }
};

return {
  json: response
};
